const ctx = $('Consolidar contexto').first().json;
let lista = $('Buffer: leer mensajes').first().json.mensajes_lista;
if (!Array.isArray(lista)) lista = lista ? [lista] : [];
// Redis push tail=true => orden cronológico. Unir con salto de línea.
const combinado = lista.filter(Boolean).join('\n').trim() || ctx.user_message;
return [{ json: Object.assign({}, ctx, { user_message: combinado }) }];

const ctx = $('Determinar rol').first().json;

// ---- Ficha del cliente en el CRM (memoria de largo plazo) ----
const fichaCliente = (() => {
  const l = ctx.lead;
  if (!l) return '(Sin ficha en el CRM: es un contacto nuevo o todavía no mostró interés de compra.)';
  const v = (x) => (x === null || x === undefined || String(x).trim() === '') ? null : String(x).trim();
  const filas = [
    ['Nombre', v(l.nombre)], ['Negocio', v(l.negocio)], ['Producto de interés', v(l.producto)],
    ['Etapa comercial', v(l.estado)], ['Comuna', v(l.comuna)],
    ['Vendedor asignado', v(l.vendedor)],
    ['Cita', v(l.fecha_cita) ? (l.fecha_cita + (v(l.hora_cita) ? ' ' + l.hora_cita : '') + (v(l.agenda) ? ' (' + l.agenda + ')' : '')) : null],
    ['Cliente desde', v(l.desde)],
  ].filter(([, x]) => x);
  return filas.length ? filas.map(([k, x]) => '- ' + k + ': ' + x).join('\n') : '(Ficha en el CRM sin datos todavía.)';
})();
const rows = $input.all().map(i => i.json).filter(r => r && r.role && r.content).reverse();
const history = rows.map(r => ({ role: r.role, content: r.content }));
const historyText = history.map(h => h.role + ': ' + h.content).join('\n');

// ---- Ficha del agente por empresa (agente_empresas_config.config) ----
// Cada bloque tiene un texto por defecto genérico; la empresa 1 (Sofía) guarda en su
// ficha el texto original de la panadería, así que su comportamiento no cambia.
const cfg = (ctx.config && typeof ctx.config === 'object') ? ctx.config : {};
const asist = ctx.nombre_asistente || 'Asistente';
const empresaNom = ctx.nombre_empresa || 'la empresa';
const t = (v, d) => (typeof v === 'string' && v.trim()) ? v.trim() : d;
const sub = s => String(s || '').split('{asistente}').join(asist).split('{empresa}').join(empresaNom);
const neg = cfg.negocio || {}, cat = cfg.catalogo || {}, tono = cfg.tono || {}, ag = cfg.agenda || {};
const menu = cfg.menu || {}, interes = cfg.interes || {};
const DIAS = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];

const descripcion = t(neg.descripcion, '')
  ? ', ' + sub(neg.descripcion)
  : '. Respondes consultas de productos y precios, ayudas a tus clientes y agendas citas, siempre usando las HERRAMIENTAS disponibles.';

const categorias_menu = t(cat.categorias_menu, 'las categorías de nuestro catálogo');

let catalogo = t(cat.texto, '');
if (!catalogo) {
  const l = ['## Catálogo — cómo atender consultas de productos',
    '- Categorías principales del negocio: ' + categorias_menu + '.',
    '- Si el cliente pregunta en general ("qué venden", "qué productos tienes"), menciona brevemente esas categorías y pregúntale cuál quiere ver CON PRECIO. No recites productos de memoria.',
    '- Cuando elija una categoría o nombre un producto, usa stock_producto pasando SOLO la(s) palabra(s) clave (sin relleno como "de" o "por favor"). Si da vacío, reintenta con una palabra más general antes de decir que no hay.',
    '- DISPONIBILIDAD: ' + t(cat.disponibilidad, 'los productos que devuelve la herramienta están disponibles; para pedidos grandes o urgentes, sugiere confirmar con un vendedor.')];
  if (t(cat.unidad, '')) l.push('- Unidad de venta: ' + cat.unidad + '. Si no especifican, aclara la unidad.');
  if (Array.isArray(cat.sinonimos)) cat.sinonimos.forEach(s => { if (s && s.dice && s.buscar) l.push('- Si el cliente dice "' + s.dice + '" → busca "' + s.buscar + '".'); });
  catalogo = l.join('\n');
}
catalogo = sub(catalogo);

const escalamiento = sub(t(cfg.escalamiento, 'Ofrece derivar a un vendedor cuando: el cliente quiera cerrar un pedido, negociar precios o condiciones, haya un reclamo, o lleves 3 turnos sin resolver su necesidad.'));

let tonoTxt = t(tono.texto, '');
if (!tonoTxt) {
  const usted = tono.trato === 'usted';
  tonoTxt = [
    usted ? 'Habla cordial y respetuoso, tratando al cliente SIEMPRE de USTED (nunca de tú). IMPORTANTE: aunque los ejemplos de estas instrucciones estén escritos en tú, TÚ respondes siempre de usted ("¿Le gustaría…?", "le muestro", "¿en qué le ayudo?"). Cálido pero profesional.'
          : 'Habla CERCANO Y NATURAL, tuteando al cliente (de TÚ, no de usted). Cálido pero profesional, sin sonar acartonado.',
    '- Frases CORTAS y directas. Evita fórmulas rígidas ("no dude en", "hágamelo saber").',
    '- Saludo/bienvenida en el primer mensaje: ' + t(tono.saludo, usted ? "'¡Hola! 😊 Soy {asistente}, de {empresa}. ¿En qué le puedo ayudar?'" : "'¡Hola! 😊 Soy {asistente}. Cuéntame, ¿en qué te puedo ayudar?'"),
    '- Emojis con moderación (' + t(tono.emojis, '😊') + '), no en cada frase.',
    '- Respuestas BREVES para WhatsApp: máximo 4-5 frases.',
    '- Formatea montos en pesos chilenos: $1.234 (punto de miles, sin decimales).',
    '- Muestra los productos con el nombre tal como viene del catálogo (stock_producto).'
  ].join('\n');
}
tonoTxt = sub(tonoTxt);

const info = [];
if (t(neg.horario, '')) info.push('- Horario de atención: ' + neg.horario + '.');
if (t(neg.direccion, '')) info.push('- Dirección: ' + neg.direccion + '.');
if (t(neg.despacho, '')) info.push('- Despacho / delivery: ' + neg.despacho);
if (t(neg.pagos, '')) info.push('- Medios de pago: ' + neg.pagos);
if (t(neg.pedido_minimo, '')) info.push('- Pedido mínimo: ' + neg.pedido_minimo);
if (t(neg.politicas, '')) info.push('- Políticas: ' + neg.politicas);
if (t(neg.no_prometer, '')) info.push('- NUNCA prometas: ' + neg.no_prometer);
if (Array.isArray(cfg.faq)) cfg.faq.forEach(f => { if (f && f.p && f.r) info.push('- Si preguntan "' + f.p + '" → ' + f.r); });
const info_negocio = info.length ? '## Información del negocio (úsala para responder; no inventes nada fuera de esto)\n' + sub(info.join('\n')) : '';

const categorias_interes = (Array.isArray(interes.categorias) ? interes.categorias.map(c => c && c.nombre).filter(Boolean) : []).join(', ') || 'Otro';

let agenda;
if (ag.activa === false) {
  agenda = '## AGENDA\nEste negocio NO agenda citas por WhatsApp. Si el cliente quiere agendar, ofrécele que un vendedor lo contacte para coordinar. NO uses las tools de calendario.';
} else {
  const tipo = t(ag.tipo, 'reunión');
  const ust = tono.trato === 'usted';
  const pideCorreo = ag.pide_correo !== false;
  const datos = pideCorreo ? 'fecha, hora y correo' : 'fecha y hora';
  let horario = '';
  const restringido = (Array.isArray(ag.dias) && ag.dias.length > 0) || !!(ag.hora_inicio && ag.hora_fin);
  if (Array.isArray(ag.dias) && ag.dias.length) horario += 'Días disponibles: ' + ag.dias.map(d => DIAS[d]).filter(Boolean).join(', ') + '. ';
  if (ag.hora_inicio && ag.hora_fin) horario += 'Horario: de ' + ag.hora_inicio + ' a ' + ag.hora_fin + ' hrs. ';
  if (ag.duracion_min) horario += 'Cada ' + tipo + ' dura ' + ag.duracion_min + ' minutos. ';
  if (ag.anticipacion_horas) horario += 'Se agenda con al menos ' + ag.anticipacion_horas + ' horas de anticipación. ';
  if (ag.lugar) horario += 'Lugar: ' + ag.lugar + '. ';
  agenda = [
    '## AGENDAR ' + tipo.toUpperCase() + ' — EL SISTEMA LA CREA, TÚ SOLO PIDES LOS DATOS',
    'El sistema agenda la ' + tipo + ' AUTOMÁTICAMENTE en segundo plano cuando tiene ' + datos + '. Tu única tarea es RECOPILAR esos datos con naturalidad.',
    horario ? '- ' + horario.trim() + (restringido ? ' Si el cliente pide un día u hora fuera de esto, explícale con amabilidad y ofrécele otra opción dentro del horario. ANTES de rechazar, compara el día pedido con la lista de días disponibles y la hora con el horario: si calza, ESTÁ disponible y NO lo rechaces (aunque antes en la conversación hayas rechazado otro día).' : '') : '',
    '- Para agendar solo necesitas: **' + datos + '** (el motivo es opcional). **NO pidas el nombre del local/negocio.**',
    '- Si FALTAN datos, pídelos' + (pideCorreo ? (ust ? " ('¿para qué fecha y hora? ¿a qué correo le envío la invitación?')." : " ('¿para qué fecha y hora? ¿a qué correo te envío la invitación?').") : (ust ? " ('¿para qué fecha y hora le acomoda?')." : " ('¿para qué fecha y hora te acomoda?').")),
    "- **PROHIBIDO afirmar que agendaste.** Cuando el cliente da " + datos + ", tu ÚNICA respuesta permitida es EXACTAMENTE algo como: 'Perfecto, coordino la " + tipo + " y " + (ust ? 'le' : 'te') + " llega la confirmación en un momento 😊'. NUNCA digas 'quedó agendada', 'está agendada', 'te envié la invitación', 'nos vemos ahí' ni menciones la hora como confirmada — el SISTEMA agenda y confirma él mismo justo después de tu mensaje. Si tú también confirmas, el cliente recibe DOS confirmaciones (mala experiencia). Solo di que estás coordinando, nada más.",
    '- NO uses las tools de calendario tú mismo; el sistema se encarga.',
    '- Tú NO conoces la disponibilidad del calendario: NUNCA digas que un horario está ocupado o no disponible, ni propongas otra hora por tu cuenta, salvo que el día u hora pedidos estén FUERA de los días/horario indicados arriba. Si el cliente dio los datos necesarios, responde SOLO la frase de coordinación.'
  ].filter(Boolean).join('\n');
}

const menuDef = {
  texto_owner: 'Hola 👋 ¿Qué necesita? Elija una opción o escríbame directo (ej: "ventas de enero", "top productos").',
  texto_cliente: 'Hola 👋 ¿En qué le ayudo? Elija una opción o escríbame su consulta.',
  botones_owner: [{ id: 'ventas_periodo', title: 'Ventas' }, { id: 'buscar_producto', title: 'Buscar producto' }, { id: 'agendar', title: 'Agendar reunión' }],
  botones_cliente: [{ id: 'ver_productos', title: 'Ver productos' }, { id: 'precios', title: 'Precios' }, { id: 'agendar', title: 'Agendar' }]
};
const perfilMenu = {
  texto_owner: t(menu.texto_owner, menuDef.texto_owner),
  texto_cliente: t(menu.texto_cliente, menuDef.texto_cliente),
  botones_owner: Array.isArray(menu.botones_owner) && menu.botones_owner.length ? menu.botones_owner.slice(0, 3) : menuDef.botones_owner,
  botones_cliente: Array.isArray(menu.botones_cliente) && menu.botones_cliente.length ? menu.botones_cliente.slice(0, 3) : menuDef.botones_cliente
};

return [{ json: {
  empresa: ctx.empresa,
  nombre_empresa: ctx.nombre_empresa,
  nombre_asistente: ctx.nombre_asistente,
  rol: ctx.rol,
  rut_cliente: ctx.rut_cliente,
  from: ctx.from,
  phone_number_id: ctx.phone_number_id,
  user_message: ctx.user_message,
  message_id: ctx.message_id,
  history,
  ficha_cliente: fichaCliente,
  history_text: historyText || '(sin historial previo)',
  config: cfg,
  negocio_configurado: cfg.configurado === true || (cfg.configurado !== false && !!t(neg.descripcion, '')),
  perfil: { descripcion, catalogo, categorias_menu, escalamiento, tono: tonoTxt, info_negocio, categorias_interes, agenda, menu: perfilMenu, calendar_id: String(ag.calendar_id || 'primary'), fuente_catalogo: String(((cfg.fuentes || {}).catalogo || {}).tipo || 'erp_supabase') }
}}];

const ctx = $('Consolidar contexto').first().json;
const hist = ctx.history || [];
// texto = últimos turnos del USUARIO + mensaje actual (los datos pueden venir repartidos)
const histUser = hist.filter(h => h.role==='user').slice(-4).map(h=>h.content).join(' \n ');
const full = (histUser + ' \n ' + (ctx.user_message||''));
// INTENCIÓN: puede venir del historial. Pero los DATOS (hora/fecha/correo/motivo)
// se extraen SOLO del mensaje ACTUAL (si no, agarra la hora de una reunión anterior).
const low = (ctx.user_message||'').toLowerCase();
const lowFull = full.toLowerCase();
const wa = ctx.from;
// ¿hay intención de agendar? (mira historial + actual)
const ag = (ctx.config && ctx.config.agenda) || {};
if (ag.activa === false) return [{ json: { agendar:false, motivo:'agenda desactivada' } }];
const tipoAg = String(ag.tipo || 'reunión');
const quiereAgendar = /(agendar|agenda|reuni[oó]n|reunirnos|c[ií]ta|juntarnos|reservar hora|hora para)/.test(lowFull) || lowFull.includes(tipoAg.toLowerCase());
if (!quiereAgendar) return [{ json: { agendar:false, motivo:'sin intencion' } }];

// --- extraer CORREO (solo del mensaje actual) ---
const em = (ctx.user_message||'').match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);
const correo = em ? em[0] : null;

// --- extraer HORA (ej 'a las 12', '12:30', 'las 3 pm') ---
let hh=null, mm=0;
let mh = low.match(/(?:a\s+las?\s+|las\s+)?(\d{1,2})(?:[:\.](\d{2}))?\s*(am|pm|hrs|horas|h)?/);
// buscar específicamente cerca de 'las' para no agarrar el '12' de otra cosa
let mh2 = low.match(/(?:a\s+las?|las)\s+(\d{1,2})(?:[:\.](\d{2}))?\s*(am|pm)?/);
const use = mh2 || mh;
if (use) { hh = parseInt(use[1]); mm = use[2]?parseInt(use[2]):0; const ap=use[3]; if(ap==='pm'&&hh<12)hh+=12; if(ap==='am'&&hh===12)hh=0; }

// --- extraer FECHA ---
// base: ahora en Chile
const now = new Date(new Date().toLocaleString('en-US',{timeZone:'America/Santiago'}));
let fecha = null;
if (/pasado\s+ma[ñn]ana/.test(low)) { fecha = new Date(now); fecha.setDate(fecha.getDate()+2); }
else if (/ma[ñn]ana/.test(low)) { fecha = new Date(now); fecha.setDate(fecha.getDate()+1); }
else if (/hoy/.test(low)) { fecha = new Date(now); }
else {
  // días de la semana: 'el viernes', 'este lunes', 'próximo martes' → el más cercano en el futuro
  const dias = { 'domingo':0,'lunes':1,'martes':2,'mi[eé]rcoles':3,'miercoles':3,'jueves':4,'viernes':5,'s[aá]bado':6,'sabado':6 };
  let diaSemana = null;
  for (const k in dias) { if (new RegExp('\\b'+k+'\\b').test(low)) { diaSemana = dias[k]; break; } }
  if (diaSemana !== null) {
    fecha = new Date(now);
    let delta = (diaSemana - fecha.getDay() + 7) % 7;
    if (delta === 0) delta = 7; // 'el viernes' cuando hoy es viernes = el próximo
    fecha.setDate(fecha.getDate() + delta);
  } else {
    const dm = (ctx.user_message||'').match(/(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?/);
    if(dm){ const y=dm[3]?(dm[3].length===2?2000+parseInt(dm[3]):parseInt(dm[3])):now.getFullYear(); fecha=new Date(y, parseInt(dm[2])-1, parseInt(dm[1])); }
  }
}

// --- MOTIVO: quitar lo ya parseado, tomar frase de motivo ---
let motivo = 'Reunión';
const mm2 = low.match(/(?:motivo|para|sobre|por)\s+([\wáéíóúñ ]{3,60})/);
const _min = new Set(['de','del','la','las','los','el','y','o','a','en','con','por','para','un','una']);
const cap = s => (s||'').split(/\s+/).map((w,i) => { if(!w) return w; const l=w.toLowerCase(); if(i>0 && _min.has(l)) return l; return w.charAt(0).toUpperCase()+w.slice(1); }).join(' ');
if (mm2) motivo = cap(mm2[1].trim());
else { const partes=(ctx.user_message||'').split(',').map(s=>s.trim()).filter(Boolean); const ult=partes[partes.length-1]; if(ult && !/@|\d{1,2}[:h]|las |ma[ñn]ana|hoy/.test(ult)) motivo=cap(ult); }

// ¿tenemos lo mínimo? fecha + hora + correo
const pideCorreo = ag.pide_correo !== false;
const completo = !!(fecha && hh!==null && (correo || !pideCorreo) && wa);
if (!completo) return [{ json: { agendar:false, incompleto:true, tiene_fecha:!!fecha, tiene_hora:hh!==null, tiene_correo:!!correo } }];
// ANTI-LOOP PRECISO: solo bloquea si en el historial YA se confirmó ESTA MISMA fecha+hora.
// (No bloquea reuniones nuevas con otra fecha/hora, aunque el historial tenga confirmaciones viejas.)
// Construir la etiqueta de esta reunión y buscar si ya se confirmó exactamente esa.

// armar inicio/fin (1 hora) en formato local SIN zona (el nodo aplica America/Santiago)
const pad=n=>String(n).padStart(2,'0');
const y=fecha.getFullYear(), mo=pad(fecha.getMonth()+1), d=pad(fecha.getDate());
const inicio = `${y}-${mo}-${d}T${pad(hh)}:${pad(mm)}:00`;
// duración y horario permitido desde la ficha de la empresa
const durMin = Number(ag.duracion_min) || 60;
const finDate = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), hh, mm + durMin);
const fin = `${finDate.getFullYear()}-${pad(finDate.getMonth()+1)}-${pad(finDate.getDate())}T${pad(finDate.getHours())}:${pad(finDate.getMinutes())}:00`;
const DIAS = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const hm = s => { const m = String(s||'').match(/(\d{1,2}):(\d{2})/); return m ? parseInt(m[1])*60 + parseInt(m[2]) : null; };
const iniLim = hm(ag.hora_inicio), finLim = hm(ag.hora_fin), t0 = hh*60 + mm, t1 = t0 + durMin;
const diasOk = !Array.isArray(ag.dias) || !ag.dias.length || ag.dias.includes(fecha.getDay());
const horaOk = iniLim === null || finLim === null || (t0 >= iniLim && t1 <= finLim);
const antMs = (Number(ag.anticipacion_horas) || 0) * 3600000;
const cuando = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), hh, mm);
const antOk = cuando.getTime() - now.getTime() >= antMs;
if (!diasOk || !horaOk || !antOk) {
  const dTxt = Array.isArray(ag.dias) && ag.dias.length ? ag.dias.map(x => DIAS[x]).join(', ') : 'todos los días';
  const hTxt = (iniLim !== null && finLim !== null) ? ` de ${ag.hora_inicio} a ${ag.hora_fin} hrs` : '';
  const aTxt = antMs ? ` y con al menos ${ag.anticipacion_horas} horas de anticipación` : '';
  const usted = !!(ctx.config && ctx.config.tono && ctx.config.tono.trato === 'usted');
  return [{ json: { agendar:false, fuera_horario:true, wa, aviso: `Uy, ese horario no lo tengo disponible 😕. Agendo ${dTxt}${hTxt}${aTxt}. ¿Qué otro día u hora ${usted ? 'le' : 'te'} acomoda?` } }];
}
// ANTI-LOOP PRECISO: bloquear solo si el bot YA confirmó ('te agendé/agendada') Y menciona
// esta MISMA fecha en el historial. Reuniones con otra fecha SÍ se agendan.
const histBot = hist.filter(h=>h.role==='assistant').map(h=>(h.content||'').toLowerCase()).join(' || ');
const fechaStr = `${y}-${mo}-${d}`;
const confirmoAntes = /(te agend[ée]|reuni[oó]n .{0,30}agendada)/.test(histBot);
const mismaFecha = histBot.includes(fechaStr);
if (confirmoAntes && mismaFecha) return [{ json: { agendar:false, motivo:'ya_agendada_misma_fecha' } }];
const correoNeg = ag.correo_negocio ? String(ag.correo_negocio).trim() : null;
const attendees = [correo, correoNeg].filter(Boolean);
const tipoCap = tipoAg.charAt(0).toUpperCase() + tipoAg.slice(1);
const titulo = (motivo && motivo !== 'Reunión') ? `${tipoCap}: ${motivo}` : `${tipoCap} con cliente WhatsApp +${wa}`;
const descripcion = `${motivo === 'Reunión' ? tipoCap : motivo}\nCliente WhatsApp: +${wa}` + (correo ? `\nCorreo: ${correo}` : '') + `\nAgendado por ${ctx.nombre_asistente || 'el asistente'} (${ctx.nombre_empresa || ''})`;
return [{ json: { agendar:true, wa, correo, inicio, fin, motivo, titulo, descripcion, attendees, calendar_id: String(ag.calendar_id || 'primary'), lugar: ag.lugar || '', tipo: tipoAg, mensaje_ok: ag.mensaje_confirmacion || '' } }];

const ctx = $('Consolidar contexto').first().json;
// Analizar el mensaje ACTUAL + el historial reciente del cliente (por el buffer,
// un turno puede ser corto como 'de pino'; el interés/producto puede estar en turnos previos).
const histUser = (ctx.history || []).filter(h => h.role === 'user').map(h => h.content).join(' ');
const msg = ((histUser + ' ' + (ctx.user_message || ''))).toLowerCase();
const wa = ctx.from;
// Detectar producto por palabras clave del catálogo real
const cfgI = (ctx.config && ctx.config.interes) || {};
const cats = Array.isArray(cfgI.categorias) ? cfgI.categorias : [];
let producto = null;
for (const c of cats) { try { if (c && c.regex && new RegExp(c.regex, 'i').test(msg)) { producto = c.nombre; break; } } catch (e) { /* regex inválida en la ficha */ } }
// Señales de interés comercial: base genérica + las del rubro (ficha)
let interes = /(precio|valor|cu[aá]nto|cotiza|comprar|pedido|encargo|reserva|disponib|stock)/.test(msg);
if (!interes && cfgI.senales) { try { interes = new RegExp(cfgI.senales, 'i').test(msg); } catch (e) {} }
// Sin categorías en la ficha, el interés comercial basta para registrarlo como 'Otro'
if (!producto && interes && cats.length === 0) producto = 'Otro';
// Petición de HANDOFF a humano (mira SOLO el mensaje actual, no el historial)
const msgActual = (ctx.user_message || '').toLowerCase();
const pideHumano = /(vendedor|hablar con (alguien|una persona|un humano|un ejecutivo|un asesor)|con una persona|atenci[oó]n humana|asesor|ejecutivo)/.test(msgActual);
// ¿El ÚLTIMO mensaje del bot pidió el NOMBRE? Entonces la respuesta del cliente ES el nombre.
const hist = ctx.history || [];
let ultimoBot = '';
for (let i = hist.length - 1; i >= 0; i--) { if (hist[i].role === 'assistant') { ultimoBot = (hist[i].content||'').toLowerCase(); break; } }
const botPidioNombre = /(a nombre de qui[eé]n|con qui[eé]n tengo el gusto|nombre de la persona|c[oó]mo te llamas|tu nombre|qui[eé]n eres|a qui[eé]n anoto)/.test(ultimoBot);
// Capturar nombre: el mensaje actual del cliente, limpio (quitar 'soy', 'me llamo', 'local', etc.)
let nombreCap = null, negocioCap = null;
if (botPidioNombre) {
  const t = (ctx.user_message || '').trim();
  // separar posible 'nombre, local X' o 'nombre y el local es X'
  let resto = t;
  // 1) extraer el NEGOCIO si viene con marcador explícito ('local X', 'negocio X', 'mi local es X', 'del local X')
  const mNeg = t.match(/(?:mi\s+)?(?:local|negocio|tienda|restaurant\w*|caf[eé]|almac[eé]n|sushi|kiosco|food ?truck)\s+(?:se\s+llama\s+|es\s+|:\s*)?([\wáéíóúñ' ]{2,40})/i);
  if (mNeg) { negocioCap = mNeg[1].trim(); resto = t.replace(mNeg[0], '').trim(); }
  // 2) el NOMBRE es lo que queda antes de una coma/marcador (quitar prefijos 'soy', 'me llamo')
  resto = resto.replace(/[,;].*$/, '').trim();
  resto = resto.replace(/^(hola\s+)?(soy|me llamo|mi nombre es|es|soy el|soy la)\s+/i, '').trim();
  resto = resto.replace(/\s+(del|de la|de|el|la)\s*$/i, '').trim();
  // si tras quitar el negocio no queda nombre (ej. 'local los tres cerditos'), nombre queda null
  if (resto && resto.length >= 2 && resto.length <= 30 && !/^(local|negocio|el|la|los|las)$/i.test(resto)) nombreCap = resto;
  // capitalizar
  const _min = new Set(['de','del','la','las','los','el','y','o','a','en','con','por','para','un','una']);
  const cap = s => (s||'').split(/\s+/).map((w,i) => { if(!w) return w; const l=w.toLowerCase(); if(i>0 && _min.has(l)) return l; return w.charAt(0).toUpperCase()+w.slice(1); }).join(' ');
  if (nombreCap) nombreCap = cap(nombreCap);
  if (negocioCap) negocioCap = cap(negocioCap);
}
// ¿Estamos en un handoff pendiente? (la ficha ya está en Requiere Vendedor o el bot pidió nombre tras pedir vendedor)
const enHandoff = /(vendedor|pasar con|te contact|a la brevedad)/.test(ultimoBot);

const debeRegistrar = (!!producto && interes && !!wa) || (pideHumano && !!wa) || (botPidioNombre && !!nombreCap && !!wa);
const body = { contact_id: wa, phone: wa, origen_lead: 'whatsapp' };
if (producto) body.producto_interes = producto;
if (nombreCap) body.nombre = nombreCap;
if (negocioCap) body.nombre_negocio = negocioCap;
if (pideHumano) { body.estado_crm = 'Requiere Vendedor'; }
// Si el bot pidió nombre en contexto de handoff y el cliente lo dio → guardar + CORTAR (bot_activo=false)
if (botPidioNombre && nombreCap && enHandoff) { body.estado_crm = 'Requiere Vendedor'; body.bot_activo = false; }
if (!body.estado_crm) body.estado_crm = 'En Conversación';
return [{ json: Object.assign({ debeRegistrar, pideHumano, capturoNombre: !!nombreCap, corte: (botPidioNombre && nombreCap && enHandoff) }, body) }];

